SELECT QUARTER(c.signup_date) signup_quarter, DATE_TRUNC('MONTH', c.signup_date) signup_month, COUNT(DISTINCT s.monthly_fee) unique_statuss, COUNT(s.monthly_fee) monthly_fee_count FROM subscriptions s JOIN customers c ON c.id = s.customer_id WHERE c.country IN ('US', 'TH') GROUP BY QUARTER(c.signup_date), DATE_TRUNC('MONTH', c.signup_date) ORDER BY monthly_fee_count ASC, signup_quarter DESC
